CREATE TABLE "task_lists" ("id" TEXT PRIMARY KEY, "workspaceId" TEXT NOT NULL REFERENCES "workspaces"("id") ON DELETE CASCADE, "folderId" TEXT REFERENCES "list_folders"("id") ON DELETE SET NULL, "name" TEXT NOT NULL, "colorHex" TEXT, "sortOrder" INTEGER NOT NULL, "isArchived" BOOLEAN NOT NULL DEFAULT 0, "createdAt" DATETIME NOT NULL, "updatedAt" DATETIME NOT NULL, "systemRole" TEXT, "visibleRootTaskId" TEXT REFERENCES "tasks"("id") ON DELETE SET NULL, "completedAt" DATETIME);
