CREATE TABLE "tasks" ("id" TEXT PRIMARY KEY, "listId" TEXT NOT NULL REFERENCES "task_lists"("id") ON DELETE CASCADE, "parentTaskId" TEXT REFERENCES "tasks"("id") ON DELETE CASCADE, "title" TEXT NOT NULL, "notes" TEXT NOT NULL DEFAULT '', "status" TEXT NOT NULL DEFAULT 'open', "sortOrder" INTEGER NOT NULL, "dueAt" DATETIME, "estimateSeconds" INTEGER, "createdAt" DATETIME NOT NULL, "updatedAt" DATETIME NOT NULL, "sourceSystem" TEXT, "sourceId" TEXT, "itemKind" TEXT, "isPromoted" BOOLEAN, "archivedAt" DATETIME, "completedAt" DATETIME);
