CREATE TABLE "task_metadata" ("taskId" TEXT PRIMARY KEY REFERENCES "tasks"("id") ON DELETE CASCADE, "priority" INTEGER, "startAt" DATETIME, "tagsJSON" TEXT NOT NULL DEFAULT '[]', "recurrenceRule" TEXT, "matrixUrgency" INTEGER, "matrixImportance" INTEGER, "kanbanColumn" TEXT, "externalLinksJSON" TEXT NOT NULL DEFAULT '[]', "updatedAt" DATETIME NOT NULL, "focusRank" INTEGER, "planningJSON" TEXT);
