CREATE INDEX "focus_sessions_on_startedAt" ON "focus_sessions"("startedAt");
CREATE TABLE "focus_queue_items" ("id" TEXT PRIMARY KEY, "sessionId" TEXT NOT NULL REFERENCES "focus_sessions"("id") ON DELETE CASCADE, "taskId" TEXT NOT NULL REFERENCES "tasks"("id") ON DELETE CASCADE, "sortOrder" INTEGER NOT NULL, "state" TEXT NOT NULL DEFAULT 'queued', "completedAt" DATETIME, "skippedAt" DATETIME, "createdAt" DATETIME NOT NULL, "plannedSeconds" INTEGER);
CREATE INDEX "focus_queue_items_on_sessionId" ON "focus_queue_items"("sessionId");
CREATE INDEX "focus_queue_items_on_taskId" ON "focus_queue_items"("taskId");
